<div tabindex="0" role="region" aria-label="Font family CSS tokens" class="overflow-x-auto rounded-xl border border-slate-300 focus-visible:outline-2 focus-visible:outline-offset-2 dark:border-slate-600">
    <table class="w-full min-w-[40rem] text-left text-sm">
        <caption class="sr-only">Font family tokens and defaults</caption>
        <thead class="bg-slate-100 dark:bg-slate-900"><tr><th scope="col" class="px-4 py-3">Token</th><th scope="col" class="px-4 py-3">Default</th><th scope="col" class="px-4 py-3">Used for</th></tr></thead>
        <tbody class="divide-y divide-slate-300 dark:divide-slate-600">
            <tr><th scope="row" class="whitespace-nowrap px-4 py-3"><x-sirius::code>--sir-font-family</x-sirius::code></th><td class="px-4 py-3"><x-sirius::code>initial</x-sirius::code></td><td class="px-4 py-3">Main component text; keeps existing application and browser styles.</td></tr>
            <tr><th scope="row" class="whitespace-nowrap px-4 py-3"><x-sirius::code>--sir-font-family-mono</x-sirius::code></th><td class="px-4 py-3"><x-sirius::code>initial</x-sirius::code></td><td class="px-4 py-3">Inline Code and Richtext code blocks; keeps existing monospace styles.</td></tr>
            <tr><th scope="row" class="whitespace-nowrap px-4 py-3"><x-sirius::code>--sir-richtext-shortcut-font-family</x-sirius::code></th><td class="px-4 py-3"><x-sirius::code>initial</x-sirius::code></td><td class="px-4 py-3">Richtext keyboard hints; falls back to the main token, then system sans-serif.</td></tr>
        </tbody>
    </table>
</div>
